// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Property system_output_range -- Pre-Assert and Next-Assert VCs for every schema transition.
//! Each proof fn has an empty body: Verus discharges `requires ==> ensures`
//! via SMT; add proof hints in the body if a VC does not discharge.

#![allow(non_snake_case)]
#![allow(unused_variables)]
#![allow(unused_imports)]

use vstd::prelude::*;

use crate::assertions::*;
use crate::system_output_range::assertions::*;
use crate::contracts::*;
use crate::system_state::SystemState;
use crate::write_frames::*;

verus! {

/** VC[1]: Pre-Assert -- START |- A compute assumes */
pub proof fn vc_pre_assert_top_a(st: SystemState)
  requires
    sys_assert_system_output_range_START(st),
  ensures
    a::compute_spec_A_Input_Range_assume(st.system_input),
{}

/** VC[2]: Next-Assert (task) -- START + frames + A postcondition |- after_top_a */
pub proof fn vc_next_assert_task_top_a(pre: SystemState, post: SystemState)
  requires
    sys_assert_system_output_range_START(pre),
    a_local_write_frame(pre, post),
    a_global_write_frame(pre, post),
    a::compute_spec_A_Output_Range_guarantee(pre.system_input, post.top_a_output),
  ensures
    sys_assert_system_output_range_after_top_a(post),
{}

/** VC[3]: Pre-Assert -- after_top_a |- B compute assumes */
pub proof fn vc_pre_assert_top_b(st: SystemState)
  requires
    sys_assert_system_output_range_after_top_a(st),
  ensures
    b::compute_spec_B_Input_Range_assume(st.top_a_output),
{}

/** VC[4]: Next-Assert (task) -- after_top_a + frames + B postcondition |- after_top_b */
pub proof fn vc_next_assert_task_top_b(pre: SystemState, post: SystemState)
  requires
    sys_assert_system_output_range_after_top_a(pre),
    b_local_write_frame(pre, post),
    b_global_write_frame(pre, post),
    b::compute_spec_B_Output_Range_guarantee(pre.top_a_output, post.top_b_output),
  ensures
    sys_assert_system_output_range_after_top_b(post),
{}

/** VC[5]: Pre-Assert -- after_top_b |- C compute assumes */
pub proof fn vc_pre_assert_top_c(st: SystemState)
  requires
    sys_assert_system_output_range_after_top_b(st),
  ensures
    true /* no assertions at out-places */,
{}

/** VC[6]: Next-Assert (task) -- after_top_b + frames + C postcondition |- after_top_c */
pub proof fn vc_next_assert_task_top_c(pre: SystemState, post: SystemState)
  requires
    sys_assert_system_output_range_after_top_b(pre),
    c_local_write_frame(pre, post),
    c_global_write_frame(pre, post),
    c::compute_spec_C_Output_Range_guarantee(pre.top_a_output, pre.top_b_output, post.top_output),
  ensures
    sys_assert_system_output_range_after_top_c(post),
{}

/** VC[7]: Pre-Assert -- after_top_c |- OUTER_A compute assumes */
pub proof fn vc_pre_assert_outer_a(st: SystemState)
  requires
    sys_assert_system_output_range_after_top_c(st),
  ensures
    outer_a::compute_spec_A_Input_Range_assume(st.top_output),
{}

/** VC[8]: Next-Assert (task) -- after_top_c + frames + OUTER_A postcondition |- after_outer_a */
pub proof fn vc_next_assert_task_outer_a(pre: SystemState, post: SystemState)
  requires
    sys_assert_system_output_range_after_top_c(pre),
    outer_a_local_write_frame(pre, post),
    outer_a_global_write_frame(pre, post),
    outer_a::compute_spec_A_Output_Range_guarantee(pre.top_output, post.system_output),
  ensures
    sys_assert_system_output_range_after_outer_a(post),
{}

/** VC[9]: Next-Assert (control point) -- after_outer_a |- END (state unchanged) */
pub proof fn vc_next_assert_skip_t4(st: SystemState)
  requires
    sys_assert_system_output_range_after_outer_a(st),
  ensures
    sys_assert_system_output_range_END(st),
{}

} // verus!
